"""Authorization and identity tests for schema-1 migration state."""from __future__ import annotationsfrom pathlib import Pathfrom typing import Literalimport pytestfrom tests.description_cache_migration_fixture import write_legacy_inputsfrom gametool.description_cache_migration import (    DescriptionCacheMigrationOptions,    migrate_description_cache,)type CasefoldIdentity = Literal["output", "path"]@pytest.mark.parametrize("state", ("完整", "部分完成", "受限"))def test_migration_accepts_exact_published_terminal_schema1_states(    tmp_path: Path,    state: str,) -> None:    # Given    legacy_output, legacy_cache = write_legacy_inputs(tmp_path, state=state)    output = tmp_path / "trusted"    # When    result = migrate_description_cache(        DescriptionCacheMigrationOptions(legacy_output, legacy_cache, output)    )    # Then    assert result.accepted_count == 1